  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Bát cơm mới\":\nVụ mùa năm nay, nhà bà nội được mùa. Bà đem thóc mới đi xay, nấu nồi cơm đầu tiên thơm phức. Vì hạt gạo làm ra bằng mồ hôi của cả nhà nên ai cũng ăn rất trân trọng. Bà dặn: \"Mỗi hạt gạo có nắng, có mưa, có công người cày cấy.\" Tuy bữa cơm chỉ có rau luộc và cá kho nhưng cả nhà thấy ngon hơn mọi bữa tiệc. Từ đó, em không bao giờ để rơi vãi một hạt cơm.\n\nCác vế trong câu \"Vì hạt gạo làm ra bằng mồ hôi của cả nhà nên ai cũng ăn rất trân trọng.\" được nối bằng gì?"}'::jsonb, '["cặp kết từ \"Vì … nên …\"","dấu phẩy","kết từ \"và\""]'::jsonb, null, 3, 60, 5, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.02')) returning id into v_q;
