  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Mẻ lưới đầu năm\":\nTrời còn mờ sáng, đoàn thuyền đã nối đuôi nhau ra khơi. Gió thổi căng cánh buồm, sóng vỗ rì rào hai bên mạn thuyền. Đến trưa, các ngư dân thả lưới. Lưới vừa kéo lên, cá thu, cá nục nhảy lấp lánh như bạc. Mọi người reo hò vui vẻ. Chiều về, đoàn thuyền đầy ắp cá cập bến; trên bãi cát, các mẹ, các chị đã chờ sẵn. Cả làng chài rộn ràng như ngày hội.\n\nCâu \"Gió thổi căng cánh buồm, sóng vỗ rì rào hai bên mạn thuyền.\" có mấy vế?"}'::jsonb, '["2 vế","3 vế","1 vế"]'::jsonb, null, 3, 60, 5, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.02')) returning id into v_q;
