  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Hội thi gói bánh\":\nMỗi dịp Tết, làng em tổ chức hội thi gói bánh chưng. Hội thi diễn ra ở sân đình, các đội mang lá dong, gạo nếp, đỗ xanh đến từ sớm. Bánh của đội nào vuông vức, chặt tay, đẹp mắt thì được điểm cao. Bánh chưng sau khi luộc chín được bày lên mâm cỗ để cả làng cùng thưởng thức. Năm nay, đội của bà em giành giải nhất. Bà bảo, giải thưởng quý nhất là được cùng nhau giữ gìn nét đẹp ngày Tết.\n\nHội thi gói bánh diễn ra ở đâu?"}'::jsonb, '["sân đình","nhà văn hoá","trường học"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
