  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Tấm khăn thổ cẩm\":\nChị Pàng ở bản trên dệt thổ cẩm rất khéo. Trước tiên, chị se sợi lanh rồi nhuộm màu bằng lá cây rừng. Sau đó, chị ngồi bên khung cửi suốt nhiều ngày để dệt. Những hoa văn hình con chim, bông hoa, ngọn núi dần hiện lên rực rỡ. Tuy công việc tỉ mỉ và vất vả, chị vẫn luôn mỉm cười. Vì thế, mỗi tấm khăn chị dệt như chứa cả niềm vui và sự khéo léo của người phụ nữ vùng cao.\n\nTừ ngữ nối nào giúp liên kết câu thứ hai và câu thứ ba?"}'::jsonb, '["Sau đó","Trước tiên","Vì thế"]'::jsonb, null, 3, 60, 5, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.02')) returning id into v_q;
