  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Con đường mùa nước nổi\":\nÔng Sáu sống ở một vùng quê sông nước miền Tây. Ông đã ngoài bảy mươi tuổi nhưng vẫn ngày ngày chèo xuồng đưa học trò qua sông. Mùa nước nổi, đồng ruộng mênh mông như biển. Những con đường đất chìm dưới nước, chỉ còn hàng cây điên điển trổ bông vàng rực. Bọn trẻ gọi ông là \"ông lái đò của chữ\". Ông cười hiền: \"Các cháu được đến trường là ông vui rồi.\"\n\nÔng Sáu sống ở đâu?"}'::jsonb, '["một vùng quê sông nước miền Tây","một thành phố lớn","vùng núi phía Bắc"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
