  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Cực Nam Tổ quốc\":\nHè vừa rồi, em được cùng bố mẹ về thăm mũi đất cực Nam của Tổ quốc. Nơi đây, rừng đước xanh ngút ngàn chạy dài ra biển. Những cây đước đứng thẳng tắp, rễ cắm sâu xuống bùn như những chân nến khổng lồ. Chúng giữ đất, lấn biển mỗi năm thêm hàng chục mét. Đứng ở mốc toạ độ, em nhìn ra biển mênh mông. Sau đó, cả nhà chụp một tấm ảnh để nhớ mãi chuyến đi đến tận cùng đất nước.\n\nEm cùng bố mẹ về thăm nơi nào?"}'::jsonb, '["mũi đất cực Nam của Tổ quốc","đỉnh núi cao nhất","thủ đô"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
