  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Chợ nổi trên sông\":\nTừ tờ mờ sáng, chợ nổi đã họp trên khúc sông rộng. Hàng trăm chiếc ghe xuồng chở đầy trái cây, rau củ. Mỗi ghe treo một cây sào cao, trên đầu sào buộc thứ hàng mà ghe bán. Nhờ vậy, người mua nhìn từ xa đã biết ghe nào bán bí, ghe nào bán khóm. Tiếng mời chào, tiếng cười nói vang cả mặt sông. Mặt trời lên cao, chợ tan dần; những chiếc ghe lại xuôi về các ngả.\n\nChợ nổi họp ở đâu?"}'::jsonb, '["trên khúc sông rộng","ở sân đình","trong nhà văn hoá"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
