  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Chuyến thăm Văn Miếu\":\nLớp em đến thăm Văn Miếu – Quốc Tử Giám. Qua cổng lớn, chúng em đi giữa hai hàng cây cổ thụ rợp bóng. Cô hướng dẫn viên kể đây là trường đại học đầu tiên của nước ta. Những tấm bia đá đặt trên lưng rùa ghi tên các vị tiến sĩ. Chúng đã đứng đó hàng trăm năm và nhắc nhở con cháu về truyền thống hiếu học. Trước khi về, mỗi bạn viết một điều ước học tập và cất vào hộp của lớp.\n\nBia đá ghi tên những ai?"}'::jsonb, '["các vị tiến sĩ","các vị vua","các tướng lĩnh"]'::jsonb, null, 2, 50, 3, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
