  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Vườn thuốc nam của bà\":\nSau nhà bà ngoại có một vườn thuốc nam nhỏ. Bà trồng cây sả, cây gừng, cây ngải cứu, cây tía tô thành từng luống ngay ngắn. Mỗi khi cháu bị cảm, bà lại hái lá xông cho cháu. Bà kể, ông cha ta từ xưa đã biết dùng cây cỏ quanh nhà để chữa bệnh. Bà dặn em: \"Thuốc quý ở ngay quanh mình, nhưng phải hiểu biết mới dùng cho đúng.\" Em thầm hứa sẽ học thật giỏi để mai sau làm bác sĩ.\n\nVườn thuốc nam của bà ở đâu?"}'::jsonb, '["sau nhà bà ngoại","ở chợ","trên núi"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
