  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Bác kĩ sư làng em\":\nBác Thành là kĩ sư thuỷ lợi của làng em. Ngày bé, bác rất nghèo nhưng học giỏi nổi tiếng cả xã. Lớn lên, bác học ở thành phố rồi trở về quê. Vì làng hay bị hạn hán nên bác cùng mọi người đào mương, làm trạm bơm. Mùa hè năm ấy, nước mát chảy về khắp cánh đồng, lúa xanh tốt bời bời. Người làng quý bác lắm, không chỉ vì bác giỏi mà còn vì bác luôn nghĩ cho quê hương.\n\nBác Thành làm nghề gì?"}'::jsonb, '["kĩ sư thuỷ lợi","bác sĩ","thầy giáo"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
