  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Câu nào dưới đây là câu ghép?"}'::jsonb, '["Bà em kể chuyện cổ tích rất hay.","Chú mèo mướp nằm sưởi nắng bên hiên.","Mẹ đi làm, bố đi chợ, còn em ở nhà trông em bé."]'::jsonb, 'cau_ghep_chon', 1, 30, 2, 'draft', (select id from public.exercise_forms where code = 'TV.CAUGHEP'), (select id from public.learning_outcomes where code = 'V5.CAU.01')) returning id into v_q;
  insert into public.question_keys (question_id, answer_key, explanation, solution) values (v_q, '{"correct":"Mẹ đi làm, bố đi chợ, còn em ở nhà trông em bé."}'::jsonb, '{"text":"Câu ghép do nhiều vế câu ghép lại, mỗi vế có cấu tạo giống một câu đơn (có chủ ngữ, vị ngữ)."}'::jsonb, '{"text":"\"Mẹ đi làm, bố đi chợ, còn em ở nhà trông em bé.\" là câu ghép."}'::jsonb);
  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Bác kĩ sư làng em\":\nBác Thành là kĩ sư thuỷ lợi của làng em. Ngày bé, bác rất nghèo nhưng học giỏi nổi tiếng cả xã. Lớn lên, bác học ở thành phố rồi trở về quê. Vì làng hay bị hạn hán nên bác cùng mọi người đào mương, làm trạm bơm. Mùa hè năm ấy, nước mát chảy về khắp cánh đồng, lúa xanh tốt bời bời. Người làng quý bác lắm, không chỉ vì bác giỏi mà còn vì bác luôn nghĩ cho quê hương.\n\nBác cùng mọi người làm gì để chống hạn?"}'::jsonb, '["đào mương, làm trạm bơm","trồng rừng","xây chợ"]'::jsonb, null, 2, 50, 3, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
