  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Ngày hội đọc sách về Bác\":\nNhân dịp sinh nhật Bác Hồ, trường em tổ chức ngày hội đọc sách. Các bạn kể những câu chuyện về Bác: Bác chia kẹo cho các cháu thiếu nhi, Bác trồng cây ở vườn Phủ Chủ tịch, Bác viết thư khuyên các cháu chăm học. Bạn Hà đọc một đoạn thơ ca ngợi Người. Cả hội trường lặng đi xúc động. Cuối buổi, mỗi lớp viết lời hứa chăm ngoan, học giỏi để xứng đáng là cháu ngoan của Bác.\n\nNgày hội đọc sách được tổ chức nhân dịp nào?"}'::jsonb, '["sinh nhật Bác Hồ","Tết Trung thu","khai giảng"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
