  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Một nghìn con hạc giấy\":\nLớp em nghe cô kể câu chuyện về một cô bé ở Nhật Bản. Cô bé bị bệnh nặng sau chiến tranh và tin rằng gấp đủ một nghìn con hạc giấy thì điều ước sẽ thành hiện thực. Ước mơ của cô bé là thế giới không còn chiến tranh. Nghe xong, cả lớp quyết định cùng gấp hạc giấy. Mỗi con hạc mang một lời chúc hoà bình bằng nhiều thứ tiếng. Chúng em treo những chuỗi hạc đủ màu sắc ở cửa lớp, như những cánh chim bay về khắp năm châu.\n\nCô bé trong câu chuyện ở nước nào?"}'::jsonb, '["Nhật Bản","Pháp","Nga"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
