  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Một giờ tắt đèn\":\nTối thứ bảy cuối tháng Ba, khu phố em cùng hưởng ứng Giờ Trái Đất. Đúng tám giờ rưỡi, mọi nhà tắt hết đèn và các thiết bị không cần thiết. Cả khu phố chìm trong bóng tối, chỉ còn ánh trăng và ánh nến lung linh. Bọn trẻ ra sân chơi các trò dân gian:\n– bịt mắt bắt dê;\n– rồng rắn lên mây;\n– kéo co.\nMột giờ trôi qua thật nhanh. Bố bảo, tiết kiệm điện là cách nhỏ nhưng thiết thực để bảo vệ hành tinh.\n\nCác dấu gạch ngang ở đầu dòng \"– bịt mắt bắt dê; – rồng rắn lên mây; – kéo co.\" dùng để làm gì?"}'::jsonb, '["đánh dấu các ý liệt kê","đánh dấu lời nói","đánh dấu phần chú thích"]'::jsonb, null, 3, 60, 5, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.02')) returning id into v_q;
