  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Ngôi nhà thông minh\":\nNhà bác Quang vừa lắp hệ thống nhà thông minh. Chỉ cần nói một câu, đèn trong phòng đã tự bật sáng. Rèm cửa tự kéo lên khi trời sáng. Ngoài ra, chiếc máy tưới cây còn tự đo độ ẩm của đất để tưới vừa đủ nước. Tuy vậy, bác Quang vẫn dặn các con phải biết tự làm việc nhà. Bác bảo: \"Máy móc giúp ta tiện lợi, nhưng đôi tay chăm chỉ mới giúp ta trưởng thành.\"\n\nNhà bác Quang vừa lắp hệ thống gì?"}'::jsonb, '["nhà thông minh","điện mặt trời","máy điều hoà"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
