  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Lá thư gửi chính mình\":\nNgày cuối cùng của năm học lớp 5, cô giáo phát cho mỗi bạn một tờ giấy và một phong bì. Cô bảo chúng em viết thư cho chính mình của năm năm sau. Em viết về những người bạn thân, về thầy cô, về sân trường có cây bàng già. Em viết cả ước mơ trở thành nhà khoa học nghiên cứu năng lượng sạch. Cô giữ những lá thư lại và hẹn sẽ gửi đến tận tay chúng em. Ra về, ai cũng lưu luyến ngoái nhìn mái trường thân yêu.\n\nCô giáo phát cho mỗi bạn những gì?"}'::jsonb, '["một tờ giấy và một phong bì","một cuốn sách","một bức ảnh"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
